  94 // List of public paths that do not require authentication
  95 const PUBLIC_PATHS = ['/login', '/signup', '/forgot-password', '/docs', '/request', '/phone-auth'];
  96 const AUTH_PATHS = ['/login', '/signup', '/forgot-password', '/phone-auth'];
  97 
  98 // This function runs on the server for every request
  99 async function handleAuthRedirects(pathname: string) {
 100   const cookieStoreInstance = await cookies();
 101   const sessionCookie = cookieStoreInstance.get('__session')?.value;
 102   const guestCookie = cookieStoreInstance.get('__guest')?.value;
 103   
 104   const isAuthenticated = !!sessionCookie;
 105   const isGuest = !!guestCookie;
 106 
 107   // If user is authenticated and tries to access an auth page, redirect them
 108   if (isAuthenticated && AUTH_PATHS.includes(pathname)) {
 109     redirect('/builder');
 110   }
 111 
 112   // If user is not authenticated and not a guest, and tries to access a protected page, redirect them to login
 113   const isPublic = PUBLIC_PATHS.includes(pathname) || pathname === '/';
 114   if (!isAuthenticated && !isGuest && !isPublic) {
 115     redirect('/login');
 116   }
 117 }
 118 
